// 1. Normalisasi input dari Telegram Trigger atau Webhook
let rawPrompt = '4 Pilar Perlindungan Keuangan Bisnis dan Pencegahan Fraud';
let chatId = '7987566473';

if ($input.first().json.message && $input.first().json.message.text) {
  rawPrompt = $input.first().json.message.text;
  chatId = $input.first().json.message.chat.id;
} else if ($input.first().json.body && $input.first().json.body.topik) {
  rawPrompt = $input.first().json.body.topik;
  chatId = $input.first().json.body.chat_id || chatId;
} else if ($input.first().json.query && $input.first().json.query.topik) {
  rawPrompt = $input.first().json.query.topik;
  chatId = $input.first().json.query.chat_id || chatId;
}

// 2. Siapkan Prompt visual art style Behance/Gemini Web
const systemInstruction = `Anda adalah Art Director & Content Strategist PT Seventhsoft Teknologi Indonesia. Tugas Anda merancang konsep visual poster atau gambar edukasi akuntansi dan bisnis yang ramah, bersih, dan menarik (gaya vektor editorial Behance/Dribbble atau fotografi elegan profesional sesuai konteks permintaan).\n\nKeluarkan HANYA JSON murni tanpa markdown triple-backtick:\n{\n  "judul": "Judul Singkat Menarik",\n  "visual_prompt": "A detailed English visual prompt describing the scene, high resolution, 8k, professional lighting, centered composition, aesthetic masterpiece",\n  "caption_ig": "Draft caption informatif dan menarik dalam bahasa Indonesia lengkap dengan hashtag"
}\n\nPermintaan user: ${rawPrompt}`;

return {
  json: {
    topik_asli: rawPrompt,
    chat_id: chatId,
    gemini_payload: {
      contents: [
        {
          parts: [
            {
              text: systemInstruction
            }
          ]
        }
      ]
    }
  }
};

const response = $input.first().json;
let content = '';
if (response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
  content = response.candidates[0].content.parts[0].text;
} else if (response.choices && response.choices[0]?.message?.content) {
  content = response.choices[0].message.content;
}

const cleaned = content.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    judul: 'AI Generated Visual',
    visual_prompt: 'A handsome elegant Indonesian male model wearing modern formal batik blazer, studio portrait photography, cinematic lighting, 8k',
    caption_ig: 'Visual eksklusif dibuat dengan AI Agent Seventhsoft.'
  };
}

const prevData = $('Normalisasi Input Topik').first().json;
const encodedPrompt = encodeURIComponent(parsed.visual_prompt);
// Pollinations URL model=turbo (100% Gratis, Cepat, Tanpa API Key)
const pollinationsUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1080&height=1350&nologo=true&model=turbo`;

return {
  json: {
    chat_id: prevData.chat_id,
    judul: parsed.judul,
    visual_prompt: parsed.visual_prompt,
    caption: `🎨 <b>${parsed.judul}</b>\n\n${parsed.caption_ig}\n\n<i>💡 Dibuat otomatis oleh AI Agent Seventhsoft (Pollinations Engine + Gemini).</i>`,
    pollinations_url: pollinationsUrl
  }
};
